package bench;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
public final class Verify {
 interface Test {void run()throws Exception;}
 static int passed,failed;
 static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
 static void await(CountDownLatch latch)throws Exception{check(latch.await(2,TimeUnit.SECONDS),"latch never opened");}
 static int value(Future<Integer> f)throws Exception{return f.get(2,TimeUnit.SECONDS);}
 static void test(String name,Test test){try{test.run();passed++;System.out.println("PASS "+name);}catch(Throwable e){failed++;System.out.println("FAIL "+name+" "+e.getClass().getSimpleName()+": "+e.getMessage());}}
 static void settled(Gateway s,int terminals)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(System.nanoTime()<end){var m=s.snapshot();if(m.completed()+m.cancelled()+m.failed()==terminals)return;Thread.onSpinWait();}throw new AssertionError("terminal counters never converged");}
 public static void main(String[] args)throws Exception{
 test("I01 bounded-worker-budget",()->{try(var s=new Service()){var m=s.snapshot();check(m.slowWorkers()==2&&m.fastWorkers()==1,"worker budget 2+1");}});
 test("I02 bounded-queue-budget",()->{try(var s=new Service()){var m=s.snapshot();check(m.slowQueueCapacity()==2&&m.fastQueueCapacity()==2,"queue budget 2+2");}});
 test("I03 normal-seat-result",()->{try(var s=new Service()){check(value(s.submit(()->31,false))==31,"lost result");}});
 test("I04 normal-price-result",()->{try(var s=new Service()){check(value(s.submit(()->43,true))==43,"lost independent result");}});
 test("I05 two-slow-workers-enter",()->{SeatClient a=new SeatClient(),b=new SeatClient();try(var s=new Service()){s.submit(a,false);s.submit(b,false);await(a.entered);await(b.entered);check(a.leases.get()+b.leases.get()==2,"concurrency budget not used");}finally{a.release.countDown();b.release.countDown();}});
 test("I06 independent-price-isolation",()->{SeatClient a=new SeatClient(),b=new SeatClient();try(var s=new Service()){s.submit(a,false);s.submit(b,false);await(a.entered);await(b.entered);check(value(s.submit(()->99,true))==99,"price starved");}finally{a.release.countDown();b.release.countDown();}});
 test("I07 deterministic-overload-rejection",()->{SeatClient a=new SeatClient(),b=new SeatClient();try(var s=new Service()){s.submit(a,false);s.submit(b,false);await(a.entered);await(b.entered);s.submit(()->1,false);s.submit(()->2,false);boolean rejected=false;try{s.submit(()->3,false);}catch(RejectedExecutionException expected){rejected=true;}check(rejected,"fifth request silently accepted");check(s.snapshot().accepted()==4&&s.snapshot().rejected()==1,"admission accounting");}finally{a.release.countDown();b.release.countDown();}});
 test("I08 running-deadline-cancels-connection",()->{SeatClient a=new SeatClient();try(var s=new Service()){var f=s.submit(a,false);await(a.entered);check(f.cancel(true),"deadline cancellation rejected");await(a.exited);check(a.leases.get()==0&&f.isCancelled(),"lease leaked after cancellation");}finally{a.release.countDown();}});
 test("I09 queued-deadline-never-invokes-client",()->{SeatClient a=new SeatClient(),b=new SeatClient(),c=new SeatClient();try(var s=new Service()){var x=s.submit(a,false);var y=s.submit(b,false);await(a.entered);await(b.entered);var queued=s.submit(c,false);check(queued.cancel(true),"queued cancellation rejected");a.release.countDown();b.release.countDown();value(x);value(y);check(value(s.submit(()->5,false))==5,"drain failed");check(c.calls.get()==0,"cancelled queued call executed");}finally{a.release.countDown();b.release.countDown();c.release.countDown();}});
 test("I10 cancelled-queue-slot-reusable",()->{SeatClient a=new SeatClient(),b=new SeatClient();try(var s=new Service()){s.submit(a,false);s.submit(b,false);await(a.entered);await(b.entered);var cancelled=s.submit(()->1,false);s.submit(()->2,false);cancelled.cancel(true);s.submit(()->3,false);check(s.snapshot().rejected()==0,"cancelled task occupies admission slot");}finally{a.release.countDown();b.release.countDown();}});
 test("I11 downstream-error-not-success",()->{try(var s=new Service()){var f=s.submit(()->{throw new IllegalArgumentException("synthetic-seat-failure");},false);boolean propagated=false;try{value(f);}catch(ExecutionException e){propagated=e.getCause() instanceof IllegalArgumentException;}check(propagated,"failure swallowed");settled(s,1);check(s.snapshot().failed()==1&&s.snapshot().completed()==0,"error counted as success");}});
 test("I12 exact-terminal-accounting",()->{SeatClient a=new SeatClient();try(var s=new Service()){value(s.submit(()->1,false));var f=s.submit(a,false);await(a.entered);f.cancel(true);await(a.exited);settled(s,2);var m=s.snapshot();check(m.accepted()==2&&m.completed()==1&&m.cancelled()==1&&m.failed()==0,"request accounting mismatch");check(!f.cancel(true),"double terminal accepted");settled(s,2);}finally{a.release.countDown();}});
 test("I13 shutdown-cancels-queued",()->{SeatClient a=new SeatClient(),b=new SeatClient();var s=new Service();try{s.submit(a,false);s.submit(b,false);await(a.entered);await(b.entered);var q=s.submit(()->3,false);s.close();check(q.isCancelled(),"shutdown orphaned queued result");await(a.exited);await(b.exited);check(a.leases.get()+b.leases.get()==0,"shutdown leaked leases");}finally{a.release.countDown();b.release.countDown();s.close();}});
 test("I14 shutdown-rejects-new-work",()->{var s=new Service();s.close();boolean rejected=false;try{s.submit(()->1,true);}catch(RejectedExecutionException e){rejected=true;}check(rejected,"shutdown accepted work");check(s.snapshot().rejected()==1,"shutdown rejection missing");});
 test("I15 completed-result-stable",()->{try(var s=new Service()){var f=s.submit(()->121,false);check(value(f)==121&&value(f)==121&&!f.cancel(true),"completed result mutated");settled(s,1);check(s.snapshot().completed()==1,"duplicate completion");}});
 test("I16 burst-drains-without-loss",()->{SeatClient a=new SeatClient(),b=new SeatClient();try(var s=new Service()){var fa=s.submit(a,false);var fb=s.submit(b,false);await(a.entered);await(b.entered);var fc=s.submit(()->23,false);var fd=s.submit(()->29,false);a.release.countDown();b.release.countDown();check(value(fa)+value(fb)+value(fc)+value(fd)==86,"burst result mismatch");settled(s,4);check(s.snapshot().accepted()==4&&s.snapshot().completed()==4,"silent loss");}finally{a.release.countDown();b.release.countDown();}});
 System.out.println("SUMMARY passed="+passed+" failed="+failed);if(failed!=0)System.exit(1);
 }
}
